// Dependencies supplied by the surrounding kernel translation.
const fn bit(n: u32) -> u32 { 1u32 << n }

pub const I2C_ADDR_PMIC: u32 = 0x46 >> 1;
pub const I2C_ADDR_MUIC: u32 = 0x4A >> 1;
pub const I2C_ADDR_FG: u32 = 0x6C >> 1;

#[repr(C)]
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum maxim_device_type { MAXIM_DEVICE_TYPE_UNKNOWN = 0, MAXIM_DEVICE_TYPE_MAX14577, MAXIM_DEVICE_TYPE_MAX77836, MAXIM_DEVICE_TYPE_NUM }

#[repr(C)]
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum max14577_reg {
    MAX14577_REG_DEVICEID=0x00, MAX14577_REG_INT1, MAX14577_REG_INT2, MAX14577_REG_INT3,
    MAX14577_REG_STATUS1, MAX14577_REG_STATUS2, MAX14577_REG_STATUS3,
    MAX14577_REG_INTMASK1, MAX14577_REG_INTMASK2, MAX14577_REG_INTMASK3,
    MAX14577_REG_CDETCTRL1, MAX14577_REG_RFU, MAX14577_REG_CONTROL1, MAX14577_REG_CONTROL2,
    MAX14577_REG_CONTROL3, MAX14577_REG_CHGCTRL1, MAX14577_REG_CHGCTRL2, MAX14577_REG_CHGCTRL3,
    MAX14577_REG_CHGCTRL4, MAX14577_REG_CHGCTRL5, MAX14577_REG_CHGCTRL6, MAX14577_REG_CHGCTRL7,
    MAX14577_REG_END,
}
