pub enum max14577_muic_reg { MAX14577_MUIC_REG_STATUS1=0x04, MAX14577_MUIC_REG_STATUS2=0x05, MAX14577_MUIC_REG_CONTROL1=0x0C, MAX14577_MUIC_REG_CONTROL3=0x0E, MAX14577_MUIC_REG_END }
#[repr(C)]
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum max14577_muic_charger_type {
    MAX14577_CHARGER_TYPE_NONE=0x0, MAX14577_CHARGER_TYPE_USB=0x1, MAX14577_CHARGER_TYPE_DOWNSTREAM_PORT=0x2,
    MAX14577_CHARGER_TYPE_DEDICATED_CHG=0x3, MAX14577_CHARGER_TYPE_SPECIAL_500MA=0x4,
    /* Special 1A or 2A charger */ MAX14577_CHARGER_TYPE_SPECIAL_1A=0x5,
    /* max14577: reserved, used on max77836 */ MAX14577_CHARGER_TYPE_RESERVED=0x6,
    /* max14577: dead-battery charing with maximum current 100mA */ MAX14577_CHARGER_TYPE_DEAD_BATTERY=0x7,
    /* max77836: special charger (bias on D+/D-), matches register value of 0x6 */ MAX77836_CHARGER_TYPE_SPECIAL_BIAS=0xe,
    /* max77836: reserved, register value 0x7 */ MAX77836_CHARGER_TYPE_RESERVED=0xf,
}

