#[repr(C)] pub struct max14577 { pub dev: *mut device, pub i2c: *mut i2c_client, pub i2c_pmic: *mut i2c_client, pub dev_type: maxim_device_type, pub regmap: *mut regmap, pub regmap_pmic: *mut regmap, pub irq_data: *mut regmap_irq_chip_data, pub irq_data_pmic: *mut regmap_irq_chip_data, pub irq: i32 }
extern "C" { fn regmap_read(map: *mut regmap, reg: u8, val: *mut u32) -> i32; fn regmap_bulk_read(map: *mut regmap, reg: u8, buf: *mut u8, count: i32) -> i32; fn regmap_write(map: *mut regmap, reg: u8, value: u8) -> i32; fn regmap_bulk_write(map: *mut regmap, reg: u8, buf: *mut u8, count: i32) -> i32; fn regmap_update_bits(map: *mut regmap, reg: u8, mask: u8, val: u8) -> i32; }
pub type device = core::ffi::c_void; pub type i2c_client = core::ffi::c_void; pub type regmap = core::ffi::c_void; pub type regmap_irq_chip_data = core::ffi::c_void;
pub unsafe fn max14577_read_reg(map:*mut regmap, reg:u8, dest:*mut u8)->i32 { let mut val=0u32; let ret=regmap_read(map,reg,&mut val); *dest=val as u8; ret }
pub unsafe fn max14577_bulk_read(map:*mut regmap, reg:u8, buf:*mut u8, count:i32)->i32 { regmap_bulk_read(map,reg,buf,count) }
pub unsafe fn max14577_write_reg(map:*mut regmap, reg:u8, value:u8)->i32 { regmap_write(map,reg,value) }
pub unsafe fn max14577_bulk_write(map:*mut regmap, reg:u8, buf:*mut u8, count:i32)->i32 { regmap_bulk_write(map,reg,buf,count) }
pub unsafe fn max14577_update_reg(map:*mut regmap, reg:u8, mask:u8, val:u8)->i32 { regmap_update_bits(map,reg,mask,val) }

